    {
      "id": "s1",
      "op": "search_catalog",
      "args": {
        "query": "celular buena batería",
        "category": "celulares",
        "max_price": 704990,
        "attributes": {"bateria_mah": {"min": 4500}},
        "limit": 3
      }
    },
    {
      "id": "s2",
      "op": "get_product",
      "args": {"id": "P0064"}
