      "vars": {
        "nombre_aysen": "$s2.name",
        "marca_aysen": "$s2.brand",
        "precio_aysen": "$s2.price_clp",
        "rating_aysen": "$s2.avg_rating",
        "resenas_aysen": "$s3",
        "nombre_op1": "$s1.0.name",
        "precio_op1": "$s1.0.price_clp",
        "id_op1": "$s1.0.id",
        "nombre_op2": "$s1.1.name",
        "precio_op2": "$s1.1.price_clp",
        "id_op2": "$s1.1.id",
        "nombre_op3": "$s1.2.name",
        "precio_op3": "$s1.2.price_clp",
        "id_op3": "$s1.2.id"
      }
    }
  ]
}
